#!/usr/bin/env bash
# atlas-commerce oracle for one step (generated by scripts/atlas/compile_atlas.py).
# Used only by Harbor's oracle agent, which uploads this directory to /solution and runs it as
# the agent would: apply the step's change to /app, then deploy the named components with the
# builder key, exactly as a person would ship it.
set -euo pipefail

# --- compile-time values -----------------------------------------------------
@@CONFIG@@

SOLUTION_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ATLAS_WORKDIR"
if [ -s "$SOLUTION_DIR/change.patch" ]; then
    GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null \
        git -c safe.directory='*' -c core.hooksPath=/dev/null -c core.fsmonitor=false \
        apply --whitespace=nowarn "$SOLUTION_DIR/change.patch"
fi
args=()
for component in $ATLAS_DEPLOY; do args+=(--component "$component"); done
if [ ${#args[@]} -gt 0 ]; then
    PYTHONDONTWRITEBYTECODE=1 python3 -I -B deploy/deploy.py "${args[@]}"
fi
echo "[atlas solve] action=$ATLAS_ACTION deployed: ${ATLAS_DEPLOY:-nothing}"
